5	/// Iterator adaptor for [the `repeat()` function].
6	///
7	/// [the `repeat()` function]: repeat()
8	#[derive(Debug, Clone)]
9	pub struct Repeat<T> {
10	    element: T,
11	}
12	
13	/// Creates a parallel iterator that endlessly repeats `element` (by
14	/// cloning it). Note that this iterator has "infinite" length, so
15	/// typically you would want to use `zip` or `take` or some other
16	/// means to shorten it, or consider using
17	/// [the `repeat_n()` function] instead.
18	///
19	/// [the `repeat_n()` function]: repeat_n()
20	///
21	/// # Examples
22	///
23	/// ```
24	/// use rayon::prelude::*;
25	/// use rayon::iter::repeat;
26	/// let x: Vec<(i32, i32)> = repeat(22).zip(0..3).collect();
27	/// assert_eq!(x, vec![(22, 0), (22, 1), (22, 2)]);
28	/// ```
29	pub fn repeat<T: Clone + Send>(element: T) -> Repeat<T> {
30	    Repeat { element }
31	}
32	
33	impl<T> Repeat<T>
34	where
35	    T: Clone + Send,
36	{
37	    /// Takes only `n` repeats of the element, similar to the general
38	    /// [`take()`].
39	    ///
40	    /// The resulting `RepeatN` is an `IndexedParallelIterator`, allowing
41	    /// more functionality than `Repeat` alone.
42	    ///
43	    /// [`take()`]: IndexedParallelIterator::take()
44	    pub fn take(self, n: usize) -> RepeatN<T> {
45	        repeat_n(self.element, n)
46	    }
47	
48	    /// Iterates tuples, repeating the element with items from another
49	    /// iterator, similar to the general [`zip()`].
50	    ///
51	    /// [`zip()`]: IndexedParallelIterator::zip()
52	    pub fn zip<Z>(self, zip_op: Z) -> Zip<RepeatN<T>, Z::Iter>
53	    where
54	        Z: IntoParallelIterator<Iter: IndexedParallelIterator>,
55	    {
56	        let z = zip_op.into_par_iter();
57	        let n = z.len();
58	        self.take(n).zip(z)
59	    }
60	}
61	
62	impl<T> ParallelIterator for Repeat<T>
63	where
64	    T: Clone + Send,
65	{
66	    type Item = T;
67	
68	    fn drive_unindexed<C>(self, consumer: C) -> C::Result
69	    where
70	        C: UnindexedConsumer<Self::Item>,
71	    {
72	        let producer = RepeatProducer {
73	            element: self.element,
74	        };
75	        bridge_unindexed(producer, consumer)
76	    }
77	}
78	
79	/// Unindexed producer for `Repeat`.
80	struct RepeatProducer<T: Clone + Send> {
81	    element: T,
82	}
83	
84	impl<T: Clone + Send> UnindexedProducer for RepeatProducer<T> {
85	    type Item = T;
86	
87	    fn split(self) -> (Self, Option<Self>) {
88	        (
89	            RepeatProducer {
90	                element: self.element.clone(),
91	            },
92	            Some(RepeatProducer {
93	                element: self.element,
94	            }),
95	        )
96	    }
97	
98	    fn fold_with<F>(self, folder: F) -> F
99	    where
100	        F: Folder<T>,
101	    {
102	        folder.consume_iter(iter::repeat(self.element))
103	    }
104	}
105	
106	/// Iterator adaptor for [the `repeat_n()` function].
107	///
108	/// [the `repeat_n()` function]: repeat_n()
109	#[derive(Clone)]
110	pub struct RepeatN<T> {
111	    inner: RepeatNProducer<T>,
112	}
113	
114	/// Creates a parallel iterator that produces `n` repeats of `element`
115	/// (by cloning it).
116	///
117	/// # Examples
118	///
119	/// ```
120	/// use rayon::prelude::*;
121	/// use rayon::iter::repeat_n;
122	/// let x: Vec<(i32, i32)> = repeat_n(22, 3).zip(0..3).collect();
123	/// assert_eq!(x, vec![(22, 0), (22, 1), (22, 2)]);
124	/// ```
125	pub fn repeat_n<T: Clone + Send>(element: T, n: usize) -> RepeatN<T> {
126	    let inner = match NonZeroUsize::new(n) {
127	        Some(count) => RepeatNProducer::Repeats(element, count),
128	        None => RepeatNProducer::Empty,
129	    };
130	    RepeatN { inner }
131	}
132	
133	/// Creates a parallel iterator that produces `n` repeats of `element`
134	/// (by cloning it).
135	///
136	/// Deprecated in favor of [`repeat_n`] for consistency with the standard library.
137	#[deprecated(note = "use `repeat_n`")]
138	pub fn repeatn<T: Clone + Send>(element: T, n: usize) -> RepeatN<T> {
139	    repeat_n(element, n)
140	}
141	
142	impl<T: fmt::Debug> fmt::Debug for RepeatN<T> {
143	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
144	        let mut dbg = f.debug_struct("RepeatN");
145	        if let RepeatNProducer::Repeats(element, count) = &self.inner {
146	            dbg.field("count", &count.get())
147	                .field("element", element)
148	                .finish()
149	        } else {
150	            dbg.field("count", &0usize).finish_non_exhaustive()
151	        }
152	    }
153	}
