155	impl<T> ParallelIterator for RepeatN<T>
156	where
157	    T: Clone + Send,
158	{
159	    type Item = T;
160	
161	    fn drive_unindexed<C>(self, consumer: C) -> C::Result
162	    where
163	        C: UnindexedConsumer<Self::Item>,
164	    {
165	        bridge(self, consumer)
166	    }
167	
168	    fn opt_len(&self) -> Option<usize> {
169	        Some(self.len())
170	    }
171	}
172	
173	impl<T> IndexedParallelIterator for RepeatN<T>
174	where
175	    T: Clone + Send,
176	{
177	    fn drive<C>(self, consumer: C) -> C::Result
178	    where
179	        C: Consumer<Self::Item>,
180	    {
181	        bridge(self, consumer)
182	    }
183	
184	    fn with_producer<CB>(self, callback: CB) -> CB::Output
185	    where
186	        CB: ProducerCallback<Self::Item>,
187	    {
188	        callback.callback(self.inner)
189	    }
190	
191	    fn len(&self) -> usize {
192	        match self.inner {
193	            RepeatNProducer::Repeats(_, count) => count.get(),
194	            RepeatNProducer::Empty => 0,
195	        }
196	    }
197	}
198	
199	/// Producer for `RepeatN`.
200	#[derive(Clone)]
201	enum RepeatNProducer<T> {
202	    Repeats(T, NonZeroUsize),
203	    Empty,
204	}
205	
206	impl<T: Clone + Send> Producer for RepeatNProducer<T> {
207	    type Item = T;
208	    type IntoIter = Either<iter::RepeatN<T>, iter::Empty<T>>;
209	
210	    fn into_iter(self) -> Self::IntoIter {
211	        // We could potentially use `std::iter::RepeatN`, but we have no way to
212	        // create an empty instance without a value in hand, like `repeat_n(value, 0)`.
213	        // `Default` may solve this: https://github.com/rust-lang/rust/pull/139690
214	        if let Self::Repeats(element, count) = self {
215	            Either::Left(iter::repeat_n(element, count.get()))
216	        } else {
217	            Either::Right(iter::empty())
218	        }
219	    }
220	
221	    fn split_at(self, index: usize) -> (Self, Self) {
222	        if let Self::Repeats(element, count) = self {
223	            assert!(index <= count.get());
224	            match (
225	                NonZeroUsize::new(index),
226	                NonZeroUsize::new(count.get() - index),
227	            ) {
228	                (Some(left), Some(right)) => (
229	                    Self::Repeats(element.clone(), left),
