469	fn check_cmp_short_circuit() {
470	    // We only use a single thread in order to make the short-circuit behavior deterministic.
471	    let pool = ThreadPoolBuilder::new().num_threads(1).build().unwrap();
472	
473	    let a = vec![0; 1024];
474	    let mut b = a.clone();
475	    b[42] = 1;
476	
477	    pool.install(|| {
478	        let expected = ::std::cmp::Ordering::Less;
479	        assert_eq!(a.par_iter().cmp(&b), expected);
480	
481	        for len in 1..10 {
482	            let counter = AtomicUsize::new(0);
483	            let result = a
484	                .par_iter()
485	                .with_max_len(len)
486	                .inspect(|_| {
487	                    counter.fetch_add(1, Ordering::SeqCst);
488	                })
489	                .cmp(&b);
490	            assert_eq!(result, expected);
491	            // should not have visited every single one
492	            assert!(counter.into_inner() < a.len());
493	        }
494	    });
495	}
