1660	fn divide_and_conquer<'scope>(scope: &Scope<'scope>, counter: &'scope AtomicUsize, size: usize) {
1661	    if size > 1 {
1662	        scope.spawn(move |scope| divide_and_conquer(scope, counter, size / 2));
1663	        scope.spawn(move |scope| divide_and_conquer(scope, counter, size / 2));
1664	    } else {
1665	        // count the leaves
1666	        counter.fetch_add(1, Ordering::SeqCst);
1667	    }
1668	}
