impl<T: Clone + Send> Producer for RepeatNProducer<T> {
    type Item = T;
    type IntoIter = std::iter::Take<std::iter::Repeat<T>>;

    fn into_iter(self) -> Self::IntoIter {
        std::iter::repeat(self.element).take(self.count)
