```rust
use rayon::iter::plumbing::{
    bridge, Consumer, Folder, Producer, ProducerCallback, Reducer, UnindexedConsumer,
};
use rayon::prelude::*;

/// 自定义重复元素生成器：产出 `element` 的 `n` 份克隆
pub struct RepeatN<T> {
    element: T,
    count: usize,
}

/// 构造函数
pub fn repeat_n<T: Clone + Send>(element: T, n: usize) -> RepeatN<T> {
    RepeatN { element, count: n }
}

// ── 第一层：实现 ParallelIterator ──────────────────────────────
impl<T: Clone + Send> ParallelIterator for RepeatN<T> {
    type Item = T;

    fn drive_unindexed<C>(self, consumer: C) -> C::Result
    where
        C: UnindexedConsumer<Self::Item>,
    {
        bridge(self, consumer) // 我们有精确长度，直接借用 indexed 桥
    }

    fn opt_len(&self) -> Option<usize> {
        Some(self.len()) // 让 collect 走「已知长度」快速路径
    }
}

// ── 第二层：实现 IndexedParallelIterator ───────────────────────
impl<T: Clone + Send> IndexedParallelIterator for RepeatN<T> {
    fn drive<C>(self, consumer: C) -> C::Result
    where
        C: Consumer<Self::Item>,
    {
        bridge(self, consumer)
    }

    fn with_producer<CB>(self, callback: CB) -> CB::Output
    where
        CB: ProducerCallback<Self::Item>,
    {
        callback.callback(RepeatNProducer {
            element: self.element,
            count: self.count,
        })
    }

    fn len(&self) -> usize {
        self.count
    }
}

// ── 第三层：实现 Producer ──────────────────────────────────────
struct RepeatNProducer<T> {
    element: T,
    count: usize,
}

impl<T: Clone + Send> Producer for RepeatNProducer<T> {
    type Item = T;
    type IntoIter = std::iter::RepeatN<T>; // 本身就是双端 + 精确长度迭代器

    fn into_iter(self) -> Self::IntoIter {
        std::iter::repeat_n(self.element, self.count)
    }

    fn split_at(self, index: usize) -> (Self, Self) {
        assert!(index <= self.count);
        (
            RepeatNProducer { element: self.element.clone(), count: index },
            RepeatNProducer { element: self.element, count: self.count - index },
        )
    }
}

fn main() {
    let v: Vec<i32> = repeat_n(7, 5).into_par_iter().collect();
    println!("{v:?}");

    let sum: i64 = repeat_n(3, 1000).into_par_iter().map(|x| x as i64).sum();
    println!("sum = {sum}");
}

#[cfg(test)]
mod tests {
    use super::*;

    fn is_indexed<I: IndexedParallelIterator>(_: I) {}

    #[test]
    fn is_indexed_static() {
        is_indexed(repeat_n(4, 8));
    }

    #[test]
    fn matches_std_repeat_take() {
        for n in [0usize, 1, 2, 7, 100, 10_000] {
            let par: Vec<i32> = repeat_n(7, n).into_par_iter().collect();
            let seq: Vec<i32> = std::iter::repeat(7).take(n).collect();
            assert_eq!(par, seq);
        }
    }

    #[test]
    fn sum_and_map() {
        let par: i64 = repeat_n(3, 1000).into_par_iter().map(|x| x as i64).sum();
        let seq: i64 = std::iter::repeat(3).take(1000).map(|x| x as i64).sum();
        assert_eq!(par, seq);
    }

    #[test]
    fn indexed_benefits() {
        // enumerate/zip/rev/with_max_len 只有索引迭代器才能用
        let v: Vec<(usize, i32)> = repeat_n(5, 4).into_par_iter().enumerate().collect();
        assert_eq!(v, vec![(0, 5), (1, 5), (2, 5), (3, 5)]);

        let r: Vec<i32> = repeat_n(5, 4).into_par_iter().rev().collect();
        assert_eq!(r, vec![5, 5, 5, 5]);

        let z: Vec<(i32, i32)> = repeat_n(9, 3).into_par_iter().zip(1..=3).collect();
        assert_eq!(z, vec![(9, 1), (9, 2), (9, 3)]);

        let s: i32 = repeat_n(1, 1024).into_par_iter().with_max_len(64).sum();
        assert_eq!(s, 1024);
    }
}
```

Check details:
- `std::iter::RepeatN<T>` — is the type name `RepeatN`? Yes, `std::iter::RepeatN` (stable 1.82). It implements Iterator + DoubleEndedIterator + ExactSizeIterator for T: Clone. Hmm — does DoubleEndedIterator for RepeatN require T: Clone? next_back needs clone except last... std: `impl<T: Clone> DoubleEndedIterator for RepeatN<T>`. Yes gated on Clone. Our T: Clone + Send ✓.
- `into_par_iter()` on RepeatN — via blanket impl `impl<T: ParallelIterator> IntoParallelIterator for T` (iter/mod.rs:2433-2440). ✓
- `repeat_n(7, 5)` — type inference: element i32 from collect target ✓. T: Clone + Send ✓.
- `is_indexed(repeat_n(4, 8))` — needs element type annotation? `repeat_n(4, 8)` → i32 by default (integer literal defaults). ✓
- with_max_len returns MaxLen<Self> and requires Self: IndexedParallelIterator + Sized ✓; `.sum()` needs `Sum<i32> for i32` — via ParallelIterator::sum requires `Self::Item: Sum` ✓.
- `zip(1..=3)` — zip on IndexedParallelIterator takes Z: IntoParallelIterator<Iter: IndexedParallelIterator>. RangeInclusive<i32> — is i32 in the indexed set? From u2-l2 summary: "Range 到 i32/usize 止，RangeInclusive 仅限 8/16 位整数". So `1..=3` for i32 is NOT indexed! zip requires the other side indexed. Would fail. Use `1..4` instead (Range<i32> is indexed). Let me fix: `zip(1..4)` → vec![(9,1),(9,2),(9,3)]. ✓ Good catch.
- main: `repeat_n(3, 1000).into_par_iter().map(|x| x as i64).sum()` — element type i32, map to i64, sum i64 ✓.

Also there's a subtle question: does `#[derive]`-less RepeatN need Clone? Not required for the practice. rayon's RepeatN derives Clone but ParallelIterator doesn't require Clone of the iterator itself. Fine.

