```rust
use rayon::iter::plumbing::{Consumer, Folder, Reducer, UnindexedConsumer};
use rayon::prelude::*;

/// 数元素个数的消费者（等价于 .count()，但手写以展示协议）
struct Count;
struct CountFolder { count: u64 }
struct CountReducer;

impl Consumer<i64> for Count {
    type Folder = CountFolder;
    type Reducer = CountReducer;
    type Result = u64;

    fn split_at(self, _index: usize) -> (Self, Self, Self::Reducer) {
        (Count, Count, CountReducer) // 无内部状态，可以无限分裂
    }

    fn into_folder(self) -> Self::Folder {
        CountFolder { count: 0 }
    }

    fn full(&self) -> bool { false }
}

impl Folder<i64> for CountFolder {
    type Result = u64;

    fn consume(mut self, _item: i64) -> Self {
        self.count += 1;
        self
    }

    fn complete(self) -> u64 { self.count }
    fn full(&self) -> bool { false }
}

impl Reducer<u64> for CountReducer {
    fn reduce(self, left: u64, right: u64) -> u64 { left + right }
}

impl UnindexedConsumer<i64> for Count {
    fn split_off_left(&self) -> Self { Count }
    fn to_reducer(&self) -> Self::Reducer { CountReducer }
}

fn main() {
    // 索引路径：drive
    let n = (0..1_000).into_par_iter().map(|i| i as i64).drive(Count);
    assert_eq!(n, 1000);
    // 无索引路径：drive_unindexed
    let m = [1i64, 2, 3].par_iter().copied().drive_unindexed(Count);
    assert_eq!(m, 3);
    println!("count = {n}, {m}");
}
```

